'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let index = 0;
const N = data[index++];
const C = data[index++];

const infectedByHuman = new Array(N + 1).fill(false);

for (let c = 0; c < C; c++) {
  index++; // Pessoa infectante
  const count = data[index++];
